function UIActionBossCollectionDialog:InitData()
    self._allPoints = {}
    self._allPoints = ActionUtils.GetAllRegionPrimaryMapVo()

    self._allQuests = {}
    if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2003) then
        self._allQuests = ActionUtils.GetAllRegionAnnihilationTypeVo()
    end
end

function UIActionBossCollectionDialog:FillSelf()
    self:FillPoints()
    self:FillHelpRoles()

    CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(ActionUtils.GetDayRefreshTime()))
    CfUtils.FillText(self.TxtTime2, ActionUtils.GetRemainTime())
    --
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(ActionUtils.GetDayRefreshTime()))
    end, CountDownTime, false, true)

    CfUtils.SetActive(self.DestoryPanel, GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2003))

    -- 说明页按钮
    local RT_AnnihilationInfoBtn = self.DestoryPanel:Find("TitleGroup/TxtTitle/BtnDesc/Area")
    if isNotNull(RT_AnnihilationInfoBtn) then
        UIEventProxy.Create(RT_AnnihilationInfoBtn.gameObject).onPointerClick = function(event)
            local curDialog = UIModule.CurrentScreen:LastDialog()
            local moduleId = checkInt(curDialog.Argument.id)
            if not isNull(KTool.IsActive(curDialog)) and moduleId > 0 then
                print(curDialog.Argument.id)
                CfUtils.ShowModuleToast(curDialog.Argument.id)
            end
        end
    end
end

