function UIActionBossCollectionDialog:FillHelpRoles()
    if self._isInitScrollView1 then
        GameUtils.ReloadData(self.ScrollView1, table.count(self._allQuests))
    else
        self.ScrollView1:InitListView(table.count(self._allQuests), Bind(self, self.OnRefreshRoleIndex))
        self._isInitScrollView1 = true
    end
end

function UIActionBossCollectionDialog:OnRefreshRoleIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self._allQuests[index + 1]
    local go = cell.gameObject

    local vo = data
    if vo then
        CfUtils.FillImage(go.transform:Find("AnimRoot/ImgMonster"), vo.bossPortrait2)
    end

    SetButtonAction(go, Bind(self, self.OnBtnMatch, data))
    return cell
end

