function UIActionBossCollectionDialog:FillPoints()
    if self._isInitScrollView then
        GameUtils.ReloadData(self.ScrollView, table.count(self._allPoints))
    else
        self.ScrollView:InitListView(table.count(self._allPoints), Bind(self, self.OnRefreshIndex))
        self._isInitScrollView = true
    end
end

function UIActionBossCollectionDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self._allPoints[index + 1]

    local pointData 
    local t = ActionUtils.GetAllRegionSecondMapPointId(data.id)
    --找出boss点
    for k, id in pairs(t) do
        local vo = ActionUtils.GetRegionSecondaryMapVo(id)
        if checkNumber(vo.type) == Constants.RegionSecondMapPointType.Boss then
            pointData = vo
            break
        end
    end

    local go = cell.gameObject
    local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.ActionBossCollectionDialog.UIActionBossCollectionNode")
    if scr then
        scr:Refresh(pointData, index + 1)
    end

    SetButtonAction(go, Bind(self, self.OnBtnGo, pointData))
    return cell
end

function UIActionBossCollectionDialog:OnBtnGo(data)
    if not data then
        return
    end

    local id = ActionUtils.GetBossRegionPointId(data.regionBelong)
    local isUnlock, err = ActionUtils.IsUnlockRegionalSecondPoint(id)
    if not isUnlock then
        GameUtils.Toast(err)
        return
    end

    self._keepScene = true
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionBossCollectionBossPopupDialog, parameters = {id = data.id}}, {
        --{id = Constants.UITypeIds.UIActionBossCollectionDialog }
    })
end


