                self._isInSecondMap = true
            end
        end

        self._mapGo = RegionQuestMgr:GetInstance():GetPrimaryMapGo()--CfUtils.InstantiateGo(self._loader.ResultObject.gameObject, dynamicNodeGo)
        self._mapCam = self._mapGo.transform:Find("AreaMap_01_Camera").gameObject:GetComponent(typeof(Camera))
        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIActionBossCollectionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
